export function getAvailableLicenses(): LicenseInfo[] {
  return Object.values(LICENSE_INFO);
}

export function getLicenseTemplate(type: LicenseType): string {
  const template = TEMPLATES[type];
  if (!template) {
    throw new ValidationError(`Unsupported license type: "${type}". Supported: ${Object.keys(TEMPLATES).join(', ')}`);
  }
  return template;
}

export function validateLicenseMetadata(metadata: unknown): ValidationResult<LicenseMetadata> {
  if (!metadata || typeof metadata !== 'object') {
    return { valid: true, data: {} };
  }

  const data = metadata as Record<string, unknown>;
  const errors: string[] = [];

  if (data.year !== undefined && data.year !== null) {
    const yearStr = String(data.year).trim();
    if (!/^\d{4}$/.test(yearStr)) {
      errors.push('year must be a 4-digit number or string (e.g. 2026).');
    }
  }

  if (errors.length > 0) {
    return { valid: false, errors };
  }

  return {
    valid: true,
    data: {
      author: typeof data.author === 'string' ? data.author.trim() : undefined,
      year: data.year !== undefined ? String(data.year).trim() : undefined,
      organization: typeof data.organization === 'string' ? data.organization.trim() : undefined,
      projectName: typeof data.projectName === 'string' ? data.projectName.trim() : undefined,
    },
  };
}

export function generateLicense(type: LicenseType, metadata: LicenseMetadata = {}): LicenseOutput {
  const validation = validateLicenseMetadata(metadata);
  if (!validation.valid) {
    throw new ValidationError('Invalid license metadata: ' + validation.errors.join('; '), validation.errors);
  }

  const template = getLicenseTemplate(type);
  const info = LICENSE_INFO[type];

  const currentYear = new Date().getFullYear().toString();
  const year = metadata.year ? String(metadata.year).trim() : currentYear;
  const author = (metadata.author || metadata.organization || 'The Project Contributors').trim();
  const organization = (metadata.organization || author).trim();
  const projectName = (metadata.projectName || 'Software Project').trim();

  let text = template
    .replace(/\[year\]/g, year)
    .replace(/\[author\]/g, author)
    .replace(/\[organization\]/g, organization)
    .replace(/\[project\]/g, projectName);

  return {
    spdxId: type,
    name: info.name,
    text,
    metadata: {
      year,
      author,
      organization,
      projectName,
    },
    disclaimer: LEGAL_DISCLAIMER,
  };
}
